mapper.select:
SELECT b.id, b.`name`, b.`code`, sum(d.num) AS checkTotalNumber, check_num AS checkCompleteNumber, b.unit, b.brand, a.amount, b.stock_min, b.stock_max, b.file_ids, a.avg_price FROM consumable_check c inner join consumable_check_detail d on c.id=d.check_id inner join consumable b on d.consumable_id=b.id INNER JOIN consumable_store_stock a ON a.consumable_id = b.id and c.store_id=a.store_id
c.id=#{param.checkId}
and d.status=#{param.status}
and a.store_id = #{param.storeId}
and b.id=#{param.id}
GROUP BY b.id

select consumable_id
from consumable_check_detail
where check_id = #{param.checkId}
